<script setup>
import {ref,computed,watch,onMounted} from 'vue'
import {characters,isNewCharacter} from '../data/characters'
import {api} from '../lib/api'
import {useArcade} from '../stores/arcade'
const props=defineProps({modelValue:String,locked:{type:Boolean,default:false},signup:{type:Boolean,default:false},ticketId:{type:String,default:''}}),emit=defineEmits(['update:modelValue','changed']),s=useArcade(),pending=ref(null),busy=ref(false),error=ref(''),page=ref(0);let ticketRequestKey=crypto.randomUUID()
const choices=computed(()=>props.signup?characters.filter(c=>!c.minLevel):characters),pages=computed(()=>Math.ceil(choices.value.length/4)),visible=computed(()=>Array.from({length:4},(_,i)=>choices.value[page.value*4+i]??null))
watch(()=>[props.modelValue,props.signup],()=>{page.value=Math.max(0,Math.floor(choices.value.findIndex(c=>c.id===props.modelValue)/4));pending.value=null},{immediate:true})
onMounted(async()=>{if(!props.signup&&s.user)try{await api('/collection');await s.refresh()}catch(e){error.value=e.message}})
function owned(c){return !!s.data.pet.collection?.[c.id]}
function price(c){return owned(c)?0:5000}
function unavailable(c){return (!props.signup&&s.data.pet.character==='diglett'&&s.data.pet.diglettRecovery)||!!c.minLevel&&(!s.user||s.level<c.minLevel)}
function status(c){return unavailable(c)?s.data.pet.character==='diglett'?'🔒 복구 필요':'🔒 Lv.'+c.minLevel:props.modelValue===c.id?'✓ 선택됨':props.ticketId?owned(c)?'도감 보유':'입양권 사용':props.locked?owned(c)?'선택':'5,000 P':'SELECT'}
function turn(direction){page.value=Math.max(0,Math.min(pages.value-1,page.value+direction));pending.value=null;error.value=''}
function choose(c){if(unavailable(c))return;if(c.id===props.modelValue&&props.locked)return;if(!props.locked){emit('update:modelValue',c.id);return}pending.value=c;ticketRequestKey=crypto.randomUUID();error.value=''}
async function change(){if(busy.value)return;busy.value=true;error.value='';try{await s.selectCharacter(pending.value.id,props.ticketId?{ticketId:props.ticketId,requestKey:ticketRequestKey}:{});pending.value=null;emit('changed')}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><fieldset class="character-picker"><legend>나의 파트너 선택</legend><p>{{signup?'함께 모험할 친구를 골라 주세요. 첫 선택은 무료예요.':ticketId?'포켓몬 입양권을 사용합니다. 포인트는 차감되지 않으며 강화는 새 계열의 1단계로 돌아갑니다.':'처음 만나는 포켓몬은 5,000P, 도감에 등록된 포켓몬은 무료로 변경해요. 각 포켓몬의 강화 단계는 변경 후에도 유지됩니다. 레벨·보유 아이템·스킨은 보존됩니다.'}}</p><div v-if="!signup" class="partner-pagination" aria-label="파트너 페이지"><button type="button" class="light" aria-label="이전 파트너 페이지" :disabled="busy||page===0" @click="turn(-1)">◀</button><span aria-live="polite">{{page+1}} / {{pages}} <small>{{page===0?'처음 만나는 친구들':page===pages-1?'환상의 친구 · Lv.50':page===3?'새 친구들 · Lv.30':page===2?'새 친구들 · Lv.25':'새 친구들 · Lv.20'}}</small></span><button type="button" class="light" aria-label="다음 파트너 페이지" :disabled="busy||page>=pages-1" @click="turn(1)">▶</button></div><div class="character-options"><template v-for="(c,index) in visible" :key="c?.id??'empty-'+index"><button v-if="c" type="button" :class="['character-choice',{chosen:modelValue===c.id,unowned:!signup&&!owned(c)}]" :style="{'--character-color':c.color}" :disabled="unavailable(c)||busy||(locked&&!ticketId&&modelValue!==c.id&&s.data.coins<price(c))||(!!ticketId&&owned(c))" :aria-pressed="modelValue===c.id" :aria-label="c.name+(unavailable(c)?s.data.pet.character==='diglett'?' · 복구 필요':' · Lv.'+c.minLevel+' 잠금':' 선택')" @click="choose(c)"><span v-if="!signup&&!owned(c)" class="unowned-lock" aria-hidden="true">🔒</span><span class="choice-status">{{status(c)}}</span><img :src="c.image" :alt="c.name" draggable="false"/><strong>{{c.name}} <small v-if="isNewCharacter(c)">NEW</small></strong><span class="character-type">{{c.type}}</span></button><div v-else class="character-placeholder" aria-hidden="true">◉</div></template></div><p v-if="!signup&&s.data.pet.character==='diglett'">🔒 먼저 디그다를 복구하면 파트너를 변경할 수 있어요.</p><p v-if="!signup" class="character-hint">보유 포인트 {{s.data.coins.toLocaleString()}} P · {{ticketId?'입양권 1장으로 입양':'새 친구 Lv.20·25·30 / 뮤 Lv.50'}}</p><div v-if="pending" class="partner-change-confirm" role="dialog" aria-label="파트너 변경 확인"><h3>{{pending.name}}로 변경할까요?</h3><p v-if="ticketId">입양권 1장으로 미보유 포켓몬을 입양합니다. 도감에 영구 등록되며 강화 전 1단계로 시작합니다.</p><p v-else>{{price(pending).toLocaleString()}}포인트가 차감됩니다. {{s.data.pet.collection?.[pending.id]?.completed?'최종 강화 완료 상태로 변경됩니다.':(s.data.pet.collection?.[pending.id]?.stage??1)+'단계로 선택됩니다.'}} 변경 후 잔액 {{(s.data.coins-price(pending)).toLocaleString()}} P</p><button type="button" :disabled="busy" @click="change">{{busy?'변경 중…':ticketId?'입양권 1장으로 입양':price(pending)?'5,000 P 사용하고 변경':'선택'}}</button><button type="button" class="light" :disabled="busy" @click="pending=null">취소</button><p v-if="error" role="alert">{{error}}</p></div></fieldset></template>
<style scoped>
.character-picker{min-width:0;width:100%;box-sizing:border-box}.character-picker .character-options{display:grid;grid-template-columns:repeat(4,minmax(0,1fr))!important;width:100%;max-width:none;gap:clamp(5px,.8vw,12px)}.character-picker .character-choice{min-width:0;width:100%;max-width:none;box-sizing:border-box;overflow:hidden;padding:28px 6px 12px!important}.character-picker .character-choice img{display:block;width:100%;max-width:130px;height:clamp(58px,9vw,130px)!important;object-fit:contain;margin:0 auto}.character-picker .character-choice strong{font-size:clamp(10px,1.2vw,17px);white-space:normal;overflow-wrap:anywhere}.character-picker .character-choice strong small{display:block;font-size:8px;color:#bc1757}.character-picker .choice-status{max-width:calc(100% - 8px);font-size:clamp(6px,.65vw,9px)!important;white-space:nowrap;letter-spacing:0}.character-picker .character-type{max-width:100%;font-size:clamp(7px,.7vw,10px);padding:2px 3px;box-sizing:border-box;white-space:normal}.character-choice:disabled{cursor:not-allowed}.character-choice[aria-label*="잠금"] img{filter:grayscale(.6);opacity:.6}.partner-pagination{display:grid;grid-template-columns:44px minmax(0,1fr) 44px;align-items:center;gap:8px;width:100%;box-sizing:border-box;margin:12px 0}.partner-pagination>span{text-align:center;font-size:13px;min-width:0}.partner-pagination small{display:block;font-size:10px;margin-top:5px}.partner-pagination button{display:grid;place-items:center;box-sizing:border-box;width:44px;min-height:44px;margin:0;padding:8px;justify-self:start}.partner-pagination button:last-child{justify-self:end}.character-placeholder{display:grid;place-items:center;min-width:0;border:2px dashed var(--rpg-mid);border-radius:8px;background:var(--rpg-soft);color:var(--rpg-mid);font-size:34px;opacity:.45}@media(max-width:600px){.character-picker .character-options{gap:5px}.character-picker .character-choice{padding:23px 3px 8px!important}.character-picker .character-choice img{height:58px!important}.character-picker .character-choice strong{font-size:9px}.character-picker .character-type{font-size:6px}.character-picker .choice-status{font-size:6px!important;top:6px;right:3px}.character-picker .character-choice strong small{font-size:6px}}
</style>
<style scoped>
/* Keep every carousel page the same height, including NEW labels and placeholders. */
.character-picker .character-choice{--choice-art:clamp(58px,9vw,130px);display:grid;grid-template-rows:var(--choice-art) 42px 22px;align-content:center;justify-items:center;gap:4px;height:calc(var(--choice-art) + 112px);margin:0;flex:none}.character-picker .character-choice img{height:var(--choice-art)!important;min-height:0;flex:none}.character-picker .character-choice strong{display:flex;flex-direction:column;align-items:center;justify-content:center;align-self:stretch;width:100%;margin:0;line-height:1.35;gap:2px}.character-picker .character-type{align-self:center;line-height:1.3;margin:0}.character-picker .character-placeholder{height:calc(clamp(58px,9vw,130px) + 112px);box-sizing:border-box}@media(max-width:600px){.character-picker .character-choice{--choice-art:58px;grid-template-rows:58px 28px 18px;height:144px}.character-picker .character-placeholder{height:144px}}
</style>

<style scoped>.character-choice.unowned img{opacity:.38;filter:grayscale(.35)}.character-choice.unowned{position:relative}.unowned-lock{position:absolute;left:8px;top:8px;font-size:20px;z-index:2}.character-choice.unowned:hover img{opacity:.65}@media(max-width:600px){.unowned-lock{font-size:13px;top:6px;left:5px}}</style>